; Auto-generated by scripts/generate-palette-transitions.js from src/games/excitebike/palettes/.
; Do not edit by hand -- regenerate instead.
;
; Every palette has one fixed IIgs slot layout: the IIgs palette 0 slot that each of the 32 NES
; palette RAM entries ($3F00-$3F1F) is shown in.  The layouts are chosen together, so that the
; background groups that keep the same slots across the transitions don't need their tiles
; redrawn (a group whose slots change has to be recompiled with the new swizzle table).
;
; Requires: NES_ColorToIIgs_X, NES_SetPaletteMap, RefreshPPUAttributes, PPU_MEM, SHR_PALETTES

; Swizzle tables, in the PALDATA segment (palettes.s)
PAL_TITLE_SCREEN_SWIZZLE EXT
PAL_TRACK1_SWIZZLE EXT
PAL_TRACK2_SWIZZLE EXT
PAL_TRACK3_SWIZZLE EXT
PAL_TRACK4_SWIZZLE EXT
PAL_TRACK5_SWIZZLE EXT

; Palette ids, word-aligned so they index the tables below directly.  0 = no palette.
PAL_TITLE_SCREEN equ 2
PAL_TRACK1 equ 4
PAL_TRACK2 equ 6
PAL_TRACK3 equ 8
PAL_TRACK4 equ 10
PAL_TRACK5 equ 12

; Layouts (NES color -> [slots] per group; *reserved, ~shown as):
;   title_screen
;     BG0 $02 $0F $30 $21 -> [0,1,2,3]
;     BG1 $02 $15 $02 $2A -> [0,4,5,6]
;     BG2 $02 $3C $02 $30 -> [0,7,8,9]
;     BG3 $02 $30 $02 $27 -> [0,10,8,11]
;     SP0 $02 $20 $16 $0F -> [0,12,13,1]
;     SP1 $02 $27 $13 $3C -> [0,11,14,7]
;     SP2 $02 $27 $16 $30 -> [0,11,13,2]
;     SP3 $02 -- -- -- -> [0,0,0,0]
;   track1
;     BG0 $29 *$27 $22 *$30 -> [0,1,2,3]
;     BG1 $29 $27 $18 $36 -> [0,4,5,6]
;     BG2 $29 $22 $0F $20 -> [0,7,8,9]
;     BG3 $29 $22 $0F $16 -> [0,10,8,11]
;     SP0 $29 $20 $16 $0F -> [0,9,11,8]
;     SP1 $29 $13 $20 $0F -> [0,12,9,8]
;     SP2 $29 $31 $1C $0F -> [0,13,14,8]
;     SP3 $29 $20 $19 $0F -> [0,9,15,8]
;   track2
;     BG0 $01 *$1A $26 *$33 -> [0,1,2,3]
;     BG1 $01 $11 $0C $2C -> [0,4,5,6]
;     BG2 $01 $22 $0F $20 -> [0,7,8,9]
;     BG3 $01 $22 $0F $16 -> [0,10,8,11]
;     SP0 $01 $20 $16 $0F -> [0,9,11,8]
;     SP1 $01 $13 $20 $0F -> [0,12,9,8]
;     SP2 $01 $31 $1C $0F -> [0,13,14,8]
;     SP3 $01 $20 $19 $0F -> [0,9,15,8]
;   track3
;     BG0 $02 *$26 $1C *$30 -> [0,1,2,3]
;     BG1 $02 $29 $19 $39 -> [0,4,5,6]
;     BG2 $02 $22 $0F $20 -> [0,7,8,9]
;     BG3 $02 $22 $0F $16 -> [0,10,8,11]
;     SP0 $02 $20 $16 $0F -> [0,9,11,8]
;     SP1 $02 $13 $20 $0F -> [0,12,9,8]
;     SP2 $02 $31 $1C $0F -> [0,13,2,8]
;     SP3 $02 $20 $19 $0F -> [0,9,5,8]
;   track4
;     BG0 $00 *$26 $22 *$30 -> [0,1,2,3]
;     BG1 $00 $27 $18 $37 -> [0,4,5,6]
;     BG2 $00 $22 $0F $20 -> [0,7,8,9]
;     BG3 $00 $22 $0F $16 -> [0,10,8,11]
;     SP0 $00 $20 $16 $0F -> [0,9,11,8]
;     SP1 $00 $13 $20 $0F -> [0,12,9,8]
;     SP2 $00 $31 $1C $0F -> [0,13,14,8]
;     SP3 $00 $20 $19 $0F -> [0,9,15,8]
;   track5
;     BG0 $02 *$19 $22 *$30 -> [0,1,2,3]
;     BG1 $02 $00 $2D $10 -> [0,4,5,6]
;     BG2 $02 $22 $0F $20 -> [0,7,8,9]
;     BG3 $02 $22 $0F $16 -> [0,10,8,11]
;     SP0 $02 $20 $16 $0F -> [0,9,11,8]
;     SP1 $02 $13 $20 $0F -> [0,12,9,8]
;     SP2 $02 $31 $1C $0F -> [0,13,14,8]
;     SP3 $02 $20 $19 $0F -> [0,9,15,8]

            mx    %00

; UpdatePalette
;
; X = from palette id (PAL_*, or 0 for none), Y = to palette id
;
; Switches the swizzle tables to the new palette, loads its colors (LoadPaletteColors), then redraws
; the background groups whose slots changed.  Call from the GS task (it redraws tiles).
UpdatePalette
            lda   BG_UPDATE_MASKS,x
            pha
            lda   (1,s),y
            sta   1,s                 ; 1,s = groups to redraw

            phy
            ldx   PAL_SWIZZLE_LO,y
            lda   PAL_SWIZZLE_HI,y
            jsr   NES_SetPaletteMap
            ply

            jsr   LoadPaletteColors
            pla
            jmp   RefreshPPUAttributes

; LoadPaletteColors
;
; Y = palette id.  Loads IIgs palette 0 from the current NES palette RAM, in the palette's layout,
; so the colors the game changes on the fly (fades, color cycling, ...) are shown too.  Slot 0 (the
; universal background color) is left alone: the game's $3F00 writes set it directly.
LoadPaletteColors
            lda   PAL_CELLS,y
            pha                       ; 1,s = slot map
            ldy   #31                 ; Backwards, so the BG colors win a shared slot
:loop       lda   (1,s),y
            and   #$00FF
            cmp   #$00FF
            beq   :next               ; not shown
            pha                       ; 1,s = slot * 2
            tyx
            ldal  PPU_MEM+$3F00,x
            jsr   NES_ColorToIIgs_X
            plx
            stal  SHR_PALETTES,x
:next       dey
            bpl   :loop
            pla
            rts

; DetectNESPalette
;
; X = the current palette id (0 = none).  Returns A = Y = the PAL_* id of the palette whose
; colors 1-3 are all in palette RAM (other than the reserved ones), or 0 if there is none (e.g. a
; step of a fade).  The current palette is tried first,
; then the palettes that follow it in the transitions, then the rest.
DetectNESPalette
            php
            rep   #$30
            stx   :from
            txa
            beq   :all
            jsr   :match              ; still the current palette?
            bcs   :found
            ldx   :from
            lda   PAL_SUCC,x          ; its successors, a 0-terminated list of ids
:snext      sta   :ptr
            tax
            lda:  0,x
            beq   :all
            tax
            jsr   :match
            bcs   :found
            lda   :ptr
            inc
            inc
            bra   :snext
:all        ldx   #2
:anext      jsr   :match
            bcs   :found
            inx
            inx
            cpx   #14
            bcc   :anext
            ldx   #0
:found      txy
            plp
            tya
            rts

; X = palette id.  Carry set if its colors are in palette RAM.  X is kept.  Only colors 1-3 of
; each group are compared (24 at most): color 0 is always IIgs slot 0.  One pass per group, from
; SP3 back to BG0, with its three colors compared inline.  NES colors are $00-$3F, so the $FF of a
; reserved or unused color is the only table byte with bit 7 set, and bmi skips it.
:match      phx
            lda   PAL_MATCH,x
            clc
            adc   #21
            tay                       ; Y -> the last group's 3 bytes
            ldx   #28                 ; X = the last group's palette RAM offset
            sep   #$20
            mx    %10
:group      lda:  0,y                 ; color 1
            bmi   *+8                 ; $FF = any value
            cmpl  PPU_MEM+$3F01,x
            bne   :mfail
            lda:  1,y                 ; color 2
            bmi   *+8
            cmpl  PPU_MEM+$3F02,x
            bne   :mfail
            lda:  2,y                 ; color 3
            bmi   *+8
            cmpl  PPU_MEM+$3F03,x
            bne   :mfail
            dey
            dey
            dey
            dex
            dex
            dex
            dex
            bpl   :group
            rep   #$20
            mx    %00
            plx
            sec
            rts
:mfail      rep   #$20
            plx
            clc
            rts

:from       ds    2
:ptr        ds    2

; id -> colors 1-3 of each group to match (BG0-BG3, SP0-SP3; $FF = any value: reserved or unused)
PAL_MATCH
            dw    0
            dw    PAL_TITLE_SCREEN_MATCH
            dw    PAL_TRACK1_MATCH
            dw    PAL_TRACK2_MATCH
            dw    PAL_TRACK3_MATCH
            dw    PAL_TRACK4_MATCH
            dw    PAL_TRACK5_MATCH
PAL_TITLE_SCREEN_MATCH
            db    $0F,$30,$21,$15,$02,$2A,$3C,$02,$30,$30,$02,$27   ; BG0-BG3
            db    $20,$16,$0F,$27,$13,$3C,$27,$16,$30,$FF,$FF,$FF   ; SP0-SP3
PAL_TRACK1_MATCH
            db    $FF,$22,$FF,$27,$18,$36,$22,$0F,$20,$22,$0F,$16   ; BG0-BG3
            db    $20,$16,$0F,$13,$20,$0F,$31,$1C,$0F,$20,$19,$0F   ; SP0-SP3
PAL_TRACK2_MATCH
            db    $FF,$26,$FF,$11,$0C,$2C,$22,$0F,$20,$22,$0F,$16   ; BG0-BG3
            db    $20,$16,$0F,$13,$20,$0F,$31,$1C,$0F,$20,$19,$0F   ; SP0-SP3
PAL_TRACK3_MATCH
            db    $FF,$1C,$FF,$29,$19,$39,$22,$0F,$20,$22,$0F,$16   ; BG0-BG3
            db    $20,$16,$0F,$13,$20,$0F,$31,$1C,$0F,$20,$19,$0F   ; SP0-SP3
PAL_TRACK4_MATCH
            db    $FF,$22,$FF,$27,$18,$37,$22,$0F,$20,$22,$0F,$16   ; BG0-BG3
            db    $20,$16,$0F,$13,$20,$0F,$31,$1C,$0F,$20,$19,$0F   ; SP0-SP3
PAL_TRACK5_MATCH
            db    $FF,$22,$FF,$00,$2D,$10,$22,$0F,$20,$22,$0F,$16   ; BG0-BG3
            db    $20,$16,$0F,$13,$20,$0F,$31,$1C,$0F,$20,$19,$0F   ; SP0-SP3

; id -> the ids of the palettes that can follow it (transitions), 0-terminated
PAL_SUCC
            dw    PAL_NONE_SUCC
            dw    PAL_TITLE_SCREEN_SUCC
            dw    PAL_TRACK1_SUCC
            dw    PAL_TRACK2_SUCC
            dw    PAL_TRACK3_SUCC
            dw    PAL_TRACK4_SUCC
            dw    PAL_TRACK5_SUCC
PAL_NONE_SUCC
            dw    0
PAL_TITLE_SCREEN_SUCC
            dw    PAL_TRACK1,PAL_TRACK2,PAL_TRACK3,PAL_TRACK4,PAL_TRACK5,0
PAL_TRACK1_SUCC
            dw    PAL_TRACK2,PAL_TITLE_SCREEN,0
PAL_TRACK2_SUCC
            dw    PAL_TRACK3,PAL_TITLE_SCREEN,0
PAL_TRACK3_SUCC
            dw    PAL_TRACK4,PAL_TITLE_SCREEN,0
PAL_TRACK4_SUCC
            dw    PAL_TRACK5,PAL_TITLE_SCREEN,0
PAL_TRACK5_SUCC
            dw    PAL_TRACK1,PAL_TITLE_SCREEN,0

; id -> swizzle tables (PALDATA segment, palettes.s)
PAL_SWIZZLE_LO
            dw    0
            dw    PAL_TITLE_SCREEN_SWIZZLE
            dw    PAL_TRACK1_SWIZZLE
            dw    PAL_TRACK2_SWIZZLE
            dw    PAL_TRACK3_SWIZZLE
            dw    PAL_TRACK4_SWIZZLE
            dw    PAL_TRACK5_SWIZZLE
PAL_SWIZZLE_HI
            dw    0
            dw    ^PAL_TITLE_SCREEN_SWIZZLE
            dw    ^PAL_TRACK1_SWIZZLE
            dw    ^PAL_TRACK2_SWIZZLE
            dw    ^PAL_TRACK3_SWIZZLE
            dw    ^PAL_TRACK4_SWIZZLE
            dw    ^PAL_TRACK5_SWIZZLE

; id -> slot map: for each NES palette RAM entry, the IIgs slot * 2, or $FF if it isn't loaded
; (color 0, which the game writes straight to slot 0, colors that share slot 0 with it, and
; approximated colors, which are shown in another color's slot)
PAL_CELLS
            dw    0
            dw    PAL_TITLE_SCREEN_CELLS
            dw    PAL_TRACK1_CELLS
            dw    PAL_TRACK2_CELLS
            dw    PAL_TRACK3_CELLS
            dw    PAL_TRACK4_CELLS
            dw    PAL_TRACK5_CELLS
PAL_TITLE_SCREEN_CELLS
            db    $FF,$02,$04,$06,$FF,$08,$0A,$0C,$FF,$0E,$10,$12,$FF,$14,$10,$16   ; BG0-BG3
            db    $FF,$18,$1A,$02,$FF,$16,$1C,$0E,$FF,$16,$1A,$04,$FF,$FF,$FF,$FF   ; SP0-SP3
PAL_TRACK1_CELLS
            db    $FF,$02,$04,$06,$FF,$08,$0A,$0C,$FF,$0E,$10,$12,$FF,$14,$10,$16   ; BG0-BG3
            db    $FF,$12,$16,$10,$FF,$18,$12,$10,$FF,$1A,$1C,$10,$FF,$12,$1E,$10   ; SP0-SP3
PAL_TRACK2_CELLS
            db    $FF,$02,$04,$06,$FF,$08,$0A,$0C,$FF,$0E,$10,$12,$FF,$14,$10,$16   ; BG0-BG3
            db    $FF,$12,$16,$10,$FF,$18,$12,$10,$FF,$1A,$1C,$10,$FF,$12,$1E,$10   ; SP0-SP3
PAL_TRACK3_CELLS
            db    $FF,$02,$04,$06,$FF,$08,$0A,$0C,$FF,$0E,$10,$12,$FF,$14,$10,$16   ; BG0-BG3
            db    $FF,$12,$16,$10,$FF,$18,$12,$10,$FF,$1A,$04,$10,$FF,$12,$0A,$10   ; SP0-SP3
PAL_TRACK4_CELLS
            db    $FF,$02,$04,$06,$FF,$08,$0A,$0C,$FF,$0E,$10,$12,$FF,$14,$10,$16   ; BG0-BG3
            db    $FF,$12,$16,$10,$FF,$18,$12,$10,$FF,$1A,$1C,$10,$FF,$12,$1E,$10   ; SP0-SP3
PAL_TRACK5_CELLS
            db    $FF,$02,$04,$06,$FF,$08,$0A,$0C,$FF,$0E,$10,$12,$FF,$14,$10,$16   ; BG0-BG3
            db    $FF,$12,$16,$10,$FF,$18,$12,$10,$FF,$1A,$1C,$10,$FF,$12,$1E,$10   ; SP0-SP3

; from id -> its row of to id -> background groups to redraw (bit 0 = BG0 .. bit 3 = BG3).
; From no palette (0), everything is redrawn.
BG_UPDATE_MASKS
            dw    BG_UPDATE_MASKS_NONE
            dw    BG_UPDATE_MASKS_TITLE_SCREEN
            dw    BG_UPDATE_MASKS_TRACK1
            dw    BG_UPDATE_MASKS_TRACK2
            dw    BG_UPDATE_MASKS_TRACK3
            dw    BG_UPDATE_MASKS_TRACK4
            dw    BG_UPDATE_MASKS_TRACK5
